() => {
  const V = [2140, 2380, 2915, 3060, 3475, 3890, 4210, 4035, 3380, 2890, 2520, 2869];
  const els = [...document.querySelectorAll('[data-value]')];
  if (els.length !== 12) return {ok: false, detalle: `hay ${els.length} barras con data-value (se esperaban 12)`};
  const got = els.map((e) => parseFloat(e.getAttribute('data-value')));
  const bad = got.map((g, i) => g !== V[i] ? i : -1).filter((i) => i >= 0);
  if (bad.length) return {ok: false, detalle: `valores mal en ${bad.length} barras (p. ej. mes ${bad[0] + 1}: ${got[bad[0]]} en vez de ${V[bad[0]]})`};
  const h = els.map((e) => e.getBoundingClientRect().height);
  const ratios = h.map((x, i) => x / V[i]).sort((a, b) => a - b);
  const med = ratios[6];
  const off = h.map((x, i) => Math.abs(x / V[i] - med) / med).filter((d) => d > 0.05).length;
  return {ok: off === 0 && med > 0, detalle: off ? `${off} barras con altura desproporcionada` : 'las 12 barras tienen el valor y la altura correctos'};
}
